-- 08/11/2026 — Cidades, locais e pessoas de Verrogar, Abadom e Calco.
--
-- Usuário: "vamos fazer dos reinos Verrogar, Calco, Abadom" — com cidades, locais e
-- pessoas ("O conteúdo que já existe pode pular": os textos dos reinos e as
-- pessoas já cadastradas ficam como estão). Fonte: tagmar/reinos.pdf (caps. 3.4,
-- 3.10, 3.16) e tagmar/ambientacao.pdf, escritos com a skill cronista-de-tagmar.
-- Idempotente: ON CONFLICT (slug) DO NOTHING; a capital do reino só entra se
-- estiver vazia.

BEGIN;

-- ── verrogar ──
INSERT INTO public.cidades (slug, nome, reino, capital, populacao, governante, religiao, economia, descricao, rumores, compartilhado) VALUES
($t$treva$t$, $t$Treva$t$, $t$verrogar$t$, true, NULL, $t$Rei Attos II, o Destemido, monarca absoluto e Marechal das tropas, com o conselho d’A Mesa de Aço$t$, $t$Crezir e Blator$t$, $t$Casas de pedra e um comércio feito para abastecer viajantes e tropas. Tabernas, hospedarias e estalagens vivem de soldados e aventureiros.$t$, $t$Capital e maior cidade de Verrogar, no extremo leste do reino. Foi fundada por Crássio de Alimarus num vale cercado de montanhas que roubam horas de sol: a luz chega tarde e vai embora cedo, e daí veio o nome. A cidade vive como um quartel. A muralha está sempre em reparo e reforço, patrulhas de seis ou sete homens rondam os muros e as ruas, e todo forasteiro é revistado em barricadas erguidas nas estradas, bem antes dos portões.
O dia obedece aos clarins, e até quem nunca vestiu farda aprende os toques: a alvorada pela manhã, o do almoço e o de ordem no fim da tarde, que fecha o comércio. Há ainda os toques raros, conhecidos de todos — o que manda as tropas se aprontarem para a marcha e o que manda fortificar a cidade contra ataque, este já quase esquecido.
No centro fica o Largo de Filtor, em memória do príncipe morto contra Filanti. Em volta dele estão a catedral de Crezir, de quatro torres e jeito de forte, com salões de treino e alojamentos para tropas; o Ateneu de Prata, biblioteca pública guardada há dezoito anos por Luizi Gritz; e uma casa medicinal onde iniciados na arte de curar e sacerdotes de vários deuses tratam feridos e mutilados, mandando gente junto com o exército quando ele parte. Blator tem na cidade uma bela igreja, sede da Congregação dos Guerreiros do Punho de Ferro.
O castelo do rei, a Casa Real, é todo de mármore e marfim trazidos da Levânia. Tem muitos salões, uma biblioteca fechada a quase todos, jardins com pequenos lagos onde Attos II sustenta sábios, pintores e músicos, e uma câmara onde jazem os reis, em túmulos cobertos de joias e armas, por corredores guardados por armaduras, quadros e flâmulas de batalha. Debaixo de tudo ficam as masmorras de Treva: ali escravos e prisioneiros de guerra quebram pedra e tiram sal de uma mina pobre, sob carcereiros afastados da guerra pelo próprio ódio e sob o comando do barão Vassili Aldebaram.$t$, $t$Corre na corte que Idor Maximus já se cansou do rei que educou e trama derrubá-lo. Seus espiões teriam descoberto o amor secreto da Arquiduquesa Maraila pelo sumo sacerdote Mahad Saturk; Idor usaria o segredo para jogar o rei, que ama a prima, contra ela, e contra Rens Alicante, que tomaria o partido dela. Caídos os três, os herdeiros seriam mortos e a rainha mandada de volta a Marana.
Na partilha, Paltus Valom seria Conselheiro-Mor, arquiduque e senhor das terras do oeste; Verdigius Avios, general máximo, visconde e senhor das terras do norte; e Dimitri Turrim veria seu rival Mahad anulado e a fé de Crezir feita religião oficial do reino.$t$, false),
($t$fontenova$t$, $t$Fontenova$t$, $t$verrogar$t$, false, NULL, NULL, $t$Parom começa a ter culto entre os anões que chegam aos Montes Palomares$t$, $t$A região palomar é a mina de Verrogar: dela sai o metal com que se fazem os principais equipamentos do exército.$t$, $t$Cidade da região dos Montes Palomares, onde vive Tusto Malfi, um velho mago cujas histórias têm atraído uma leva crescente de viajantes. Num reino que chama magos de bruxos e necromantes, é coisa rara um deles ser motivo de peregrinação.
À volta de Fontenova, humanos e anões erguem vilas e aldeias junto às minas e trabalham até a exaustão, tirando do chão todo o minério que puderem para virar arma e armadura. Quando um veio se esgota, a aldeia é deixada para trás e outra nasce adiante.$t$, NULL, false),
($t$sula$t$, $t$Sula$t$, $t$verrogar$t$, false, NULL, $t$Pário Dentão, alcaide$t$, $t$Sevides, cultuado nas vilas do Lago Denégrio e nas aldeias de pequeninos$t$, $t$Famosa pelo licor de frutas. Hoje também vende o fumo plantado pelos pequeninos das famílias Brocaterra e Cintasolta, que entregam toda a colheita ao alcaide.$t$, $t$Cidade à beira do Lago Denégrio, conhecida em todo o reino pelo seu licor de frutas. Perto dela fica uma aldeia de pequeninos das famílias Brocaterra e Cintasolta, que cultivam um fumo de boa fama.
Todo esse fumo vai parar nas mãos do alcaide, Pário Dentão, um meio-elfo ganancioso e sem escrúpulos. O povo pequeno tem um dito para ele: de elfo, só as orelhas.$t$, $t$Diz-se que nas cidades do reino junto ao Denégrio foram montados grandes estaleiros, onde multidões de operários trabalham às pressas para pôr na água galeras, birremes e trirremes, com saberes comprados de Calco.$t$, false),
($t$lutrucia$t$, $t$Lutrúcia$t$, $t$verrogar$t$, false, NULL, NULL, NULL, $t$Sede da frota de guerra de Verrogar.$t$, $t$Cidade encravada ao sul dos Montes Palomares, perto da foz do Rio Belrra, que nasce nos Montes Treva e desce para o Lago Denégrio. É ali que Verrogar guarda e arma seus navios de guerra.
A cidade atravessa tempos de desordem política. Desde que o experiente capitão do mar Sifrad Elério foi embora, a marinha lutruciana perde barcos e homens para piratas e para navios sem bandeira.$t$, $t$Os navios sem bandeira que atacam a frota de Lutrúcia viriam de Capela, em Filanti.
Há quem diga que a nova frota que se monta nos estaleiros do Denégrio serviria para atacar Filanti pelo oeste, por água, enquanto as tropas entram por terra através de Gironde.$t$, false),
($t$crassia$t$, $t$Crássia$t$, $t$verrogar$t$, false, NULL, NULL, NULL, $t$Vive do bronze: nas encostas próximas tiram-se estanho e cobre, metal indispensável para manter as armas e armaduras do exército.$t$, $t$Vila nova, nascida da fartura de bronze encontrada nos Montes Crássios. Cresce depressa, porque o exército não para de pedir o seu metal.
Foi a esta vila que chegou o único sinal do destacamento enviado à floresta: um corcel élfico trazendo o corpo de um tenente, crivado de flechas de feitio élfico.$t$, NULL, false),
($t$seviala$t$, $t$Seviala$t$, $t$verrogar$t$, false, NULL, NULL, NULL, NULL, $t$Centro da vida política de Verrogar. É aqui, e não mais na capital, que as autoridades do reino recebem os enviados de outras terras: depois que o encontro com os falsos emissários de Dantsen acabou com a morte do príncipe Ramum em Treva, os encontros foram mudados para Seviala.
Um dos prédios da rua principal abriga em caráter permanente as delegações de Eredra, reino com quem Verrogar mantém boas relações e de quem compra boa parte da comida. Com tanta gente importante nas ruas, a milícia está por toda parte, violenta e ostensiva, mas eficaz: nunca se registrou um atentado contra as autoridades que ela guarda.$t$, $t$Nas ruas se diz que atentados acontecem com frequência e que as autoridades os abafam.$t$, false),
($t$aberdim$t$, $t$Aberdim$t$, $t$verrogar$t$, false, NULL, NULL, NULL, $t$O comércio de guerra chega aqui ao auge: mercadores de toda sorte negociam qualquer coisa que o exército possa querer.$t$, $t$Principal forte verrogari no leste, a poucos dias de cavalgada do Rio Corbei, onde se trava a guerra contra Dantsen. Toda a força do exército que não está em campanha aquartela-se ali, o que faz de Aberdim um dos lugares mais bem guardados do reino.
Ao redor do forte nasceu uma vila de gente que chegou para lucrar com a guerra, e ela cresce a cada estação.$t$, NULL, false)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.locais (slug, nome, reino, populacao, descricao, rumores, compartilhado) VALUES
($t$floresta-finlaril$t$, $t$Floresta Finlaril$t$, $t$verrogar$t$, NULL, $t$Floresta imensa que Verrogar declara sua e Âmiem também. A Casa Real de Treva a chama oficialmente de Floresta Vermelha; os elfos, de Finlaril, a Floresta do Arqueiro. Em outros tempos formava uma só mata com as florestas de Âmiem, bem maior do que hoje.
Os verrogaris a olham com medo. O único destacamento enviado para explorá-la não voltou; dias depois, um corcel élfico entrou em Crássia carregando o corpo de um tenente, perfurado de ponta a ponta por flechas de feitio élfico.$t$, $t$Dizem que os elfos de Âmiem mantêm dentro da floresta um posto avançado de suas tropas.$t$, false),
($t$montes-palomares$t$, $t$Montes Palomares$t$, $t$verrogar$t$, NULL, $t$Grande cadeia de montanhas no norte e nordeste de Verrogar, que se estende até Marana. Coube a Verrogar no fim da Unificação. São as terras mais frias do reino: no inverno chega a nevar nos picos.
É a região das minas que armam o exército, onde humanos e anões abrem vilas junto aos veios e onde colônias de anões imigrantes começam a se firmar. No meio da cordilheira, por trilhas pouco conhecidas, fica o templo principal da Ordem dos Destemidos Senhores da Guerra, devota de Blator, que chama estas montanhas de Cordilheira dos Destemidos. Os mesmos labirintos de pedra escondem os piratas do Denégrio, e as encostas abrigam criaturas de outros planos. Aqui também nasce o Rio Lara.$t$, NULL, false),
($t$montes-crassios$t$, $t$Montes Crássios$t$, $t$verrogar$t$, NULL, $t$Montanhas altas, de picos gelados e cobertos de neve no inverno, onde vivem linces e coelhos. São habitadas por anões que trabalham o ferro e o carvão, e na encosta onde fica a vila de Crássia tiram-se estanho e cobre para o bronze do exército.
Em algum ponto destes montes ergue-se a Fortaleza dos Dragões Vermelhos, sede de uma das ordens de Crezir, que lutou com bravura contra a Seita.$t$, NULL, false),
($t$montes-solomor$t$, $t$Montes de Solomor$t$, $t$verrogar$t$, NULL, $t$Montanhas cuja maior parte está dentro de Verrogar. Ao norte delas vivia a família de guerreiros que, dividida por uma disputa de sucessão, deu origem aos verrogaris: os vencedores partiram para o sul com Crássio de Alimarus e fundaram Treva. Os estudiosos chamam esse povo antigo de solomores.
O caminho é perigoso, com harpias, trols e dragonetes. Esse é um dos motivos de Verrogar, tendo chegado tão perto, ainda não ter tomado a cidade dantseniana de Calinior.$t$, $t$Aventureiros falam de acontecimentos estranhos nos Montes de Solomor, que poderiam ser obra de um mago muito poderoso ou de um grupo deles. Não se sabe de nenhum colégio de magia no reino.$t$, false)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.npcs (slug, nome, raca, profissao, deus, idade, reino, cidade, descricao, rumores, compartilhado) VALUES
($t$dimitri_turrim$t$, $t$Dimitri Turrim$t$, NULL, $t$Grão-mestre da Sagrada Ordem de Crezir$t$, $t$Crezir$t$, NULL, $t$verrogar$t$, $t$treva$t$, $t$Sacerdote grão-mestre da Sagrada Ordem de Crezir, cuja sede é a catedral de quatro torres de Treva. Antes de vestir o hábito, serviu como soldado de Attos I em várias ocasiões.
Hoje forma acólitos e guerreiros de Crezir nos salões de treino da catedral. Com o favor da Casa Real, sua fé ganha terreno sobre a de Blator, ainda a preferida do povo.$t$, $t$Dizem que é cúmplice de Idor Maximus na trama contra o rei: em troca, veria seu rival Mahad Saturk anulado e Crezir feita religião oficial de Verrogar.$t$, false),
($t$mahad_saturk$t$, $t$Mahad Saturk$t$, $t$Humano$t$, $t$Sumo sacerdote da Congregação dos Guerreiros do Punho de Ferro de Blator$t$, $t$Blator$t$, NULL, $t$verrogar$t$, $t$treva$t$, $t$Sumo sacerdote da Congregação dos Guerreiros do Punho de Ferro, sociedade de Blator com sede numa bela igreja de Treva. É um colosso, guerreiro de grandes qualidades, de sangue lévano e verrogari, vindo das terras de fronteira do oeste e morador da capital há muitos anos.
A Arquiduquesa Maraila frequenta os cultos da sua igreja, e entre os dois há um amor secreto. Ele é o único que conhece a mulher por trás da general.$t$, $t$Os espiões de Idor Maximus teriam descoberto o romance, e o general pretende usá-lo para lançar o rei contra a prima.$t$, false),
($t$luizi_gritz$t$, $t$Luizi Gritz$t$, NULL, $t$Guardião do Ateneu de Prata$t$, NULL, NULL, $t$verrogar$t$, $t$treva$t$, $t$Administra há dezoito anos o Ateneu de Prata, a biblioteca pública do Largo de Filtor, em Treva. Antes foi assessor de Iliadril Alirond, um elfo dourado que teve de deixar a cidade às pressas depois de se desentender com a corte de então.$t$, NULL, false),
($t$vassili_aldebaram$t$, $t$Vassili Aldebaram$t$, NULL, $t$Barão, senhor das masmorras de Treva$t$, NULL, NULL, $t$verrogar$t$, $t$treva$t$, $t$Barão e primo distante de Attos II, escolhido pelo próprio rei para dirigir as masmorras sob a Casa Real. Governa o lugar com mão de ferro e assiste em pessoa à execução dos prisioneiros mais importantes.
Nas festas e audiências, suas maneiras finas destoam tanto da corte que até os mais rudes desconfiam dele.$t$, NULL, false),
($t$tusto_malfi$t$, $t$Tusto Malfi$t$, NULL, $t$Mago$t$, NULL, $t$Velho$t$, $t$verrogar$t$, $t$fontenova$t$, $t$Velho mago que vive em Fontenova, nos Montes Palomares. As histórias que correm sobre ele trazem à região um fluxo crescente de viajantes, coisa notável num reino que desconfia de toda magia.$t$, NULL, false),
($t$pario_dentao$t$, $t$Pário Dentão$t$, $t$Meio-Elfo$t$, $t$Alcaide de Sula$t$, NULL, NULL, $t$verrogar$t$, $t$sula$t$, $t$Alcaide de Sula, ganancioso e sem escrúpulos. Compra todo o fumo plantado pelos pequeninos Brocaterra e Cintasolta e fica com o negócio.
Os pequeninos dizem que, de elfo, ele só tem as orelhas.$t$, NULL, false),
($t$sifrad_elerio$t$, $t$Sifrad Elério$t$, NULL, $t$Capitão do mar$t$, NULL, NULL, $t$verrogar$t$, NULL, $t$Capitão do mar experiente que comandava a frota de Lutrúcia. Desde que deixou a cidade, a marinha de guerra de Verrogar sofre perdas seguidas para piratas e navios sem bandeira, e Lutrúcia mergulhou na desordem política.$t$, NULL, false)
ON CONFLICT (slug) DO NOTHING;
UPDATE public.reinos SET capital = $t$treva$t$ WHERE slug = $t$verrogar$t$ AND capital IS NULL;

-- ── abadom ──
INSERT INTO public.cidades (slug, nome, reino, capital, populacao, governante, religiao, economia, descricao, rumores, compartilhado) VALUES
($t$fleuter$t$, $t$Fleuter$t$, $t$abadom$t$, false, NULL, $t$Eleriom Braço-Forte$t$, $t$Maira e Sevides acima de todos; Quiris, Liris e Ganis também recebem preces, como em todo o povo abadrim.$t$, $t$Vive do que produz dentro dos próprios muros: a pesca no Lago Denégrio e uma lavoura pequena.$t$, $t$Fleuter é a última cidadela abadrim de pé, erguida perto das margens do Lago Denégrio. Os anos de ataques fizeram dela mais fortaleza que cidade, e é o último refúgio de um povo que perdeu as outras.
Muita gente bate à sua porta em busca de abrigo, e pouca encontra ali um lar. Os abadrim de Fleuter ficaram metódicos e desconfiados depois de tantas perdas, e a entrada de um estranho é discutida longamente antes de ser aceita.
A cidadela é governada por Eleriom Braço-Forte, antigo guerreiro cujas palavras pesam sobre a sobrevivência de todos. A defesa cabe a Erdral Lança do Trovão, que leva nas mãos uma das lanças da antiga Guarda de Tronum.$t$, $t$Dizem os guerreiros de Fleuter que a Lança do Trovão foi forjada com os metais arcanos da Guarda da Lança de Tronum, e que outras como ela ainda esperam nas ruínas da capital.$t$, false),
($t$anguinadar$t$, $t$Vila nômade de Anguinadar$t$, $t$abadom$t$, false, NULL, $t$Evenezior Pernas Ligeiras$t$, NULL, $t$Vive da pesca e da caça, de modo rústico para os costumes do Mundo Conhecido.$t$, $t$Anguinadar é uma das poucas vilas nômades que ainda percorrem a beira do Lago Denégrio, na faixa de terra que vai do Rio Mam ao Rio Baloc. Passa quase metade do ano em marcha ao longo dessa margem, montando e desmontando acampamento.
Seu povo é feito dos abadrim que se recusaram a deixar a terra natal, mesmo sabendo que ficar significava uma vida de sacrifícios. Como nas outras comunidades do reino, os anciões julgam as disputas e ditam as regras, e as penas mais duras, o ostracismo e a morte, quase nunca são aplicadas.
A vila é guiada pelo rastreador Evenezior Pernas Ligeiras. São os caçadores que escolhem as rotas longe dos monstros e a época certa de partir, e por isso são os mais respeitados entre os seus.$t$, NULL, false)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.locais (slug, nome, reino, populacao, descricao, rumores, compartilhado) VALUES
($t$deiamom$t$, $t$Deiamom$t$, $t$abadom$t$, NULL, $t$Deiamom foi a primeira cidade de Abadom e sua capital antiga, encravada no alto da Cordilheira de Sotopor, no centro do reino. Uma das lendas diz que foi a única cidade de Tagmar que não ruiu por inteiro no cataclismo, e que sua reconstrução terminou por volta de 15 D.C.
Os bardos abadrim cantam seus jardins presos à rocha da montanha, as fontes de águas termais e os aquedutos que levavam água à capital. Quando o comércio marítimo cresceu, a família real desceu para o litoral, e Deiamom ficou como cidade da cultura e da história, onde se fundaram colégios de magia e se abriram lojas arcanas.
Hoje está perdida entre os picos e só existe nas canções. Ainda assim é um dos lugares mais procurados do reino, pela coleção de arte arcana que dizem guardar.$t$, $t$Dizem as lendas que em Deiamom ainda repousam pergaminhos que contam a história de Tagmar desde meados do Segundo Ciclo, além de outros com magias há muito esquecidas. Os poucos aventureiros que chegam a encontrar a cidade, no meio da Cordilheira de Sotopor, morrem por lá ou voltam loucos.$t$, false),
($t$tronum$t$, $t$Ruínas de Tronum$t$, $t$abadom$t$, NULL, $t$Tronum foi fundada em 570 D.C. na costa ocidental, junto ao mar e perto das minas de Petroferro, para ser a nova capital de Abadom. Tinha grandes portos, estalagens onde se ouviam todas as línguas e ruas de comércio onde se achava de tudo. Por ali passava quase todo o ferro de Tagmar, e as armas forjadas com ele.
Nela vivia a Guarda da Lança de Tronum, a elite do exército abadrim, assim chamada em honra de um rei antigo que, contam, matou um dragão com uma lança. Ali morou também Nurabissal, o último rei, cercado por um harém de cinquenta mulheres e pelos tesouros das minas.
Na noite seguinte à vitória no rio Baloc, o palácio real foi destruído sem deixar sequer cinzas. A cidade caiu nas mãos da Seita em 1340 D.C. e foi arrasada de vez pelos dragões em 1420 D.C. Hoje suas rotas estão perdidas, e os barcos que aportam na costa ocidental trazem aventureiros atrás dos tesouros de seus castelos e masmorras.$t$, $t$Contam que os reis de Abadom guardavam seus tesouros na masmorra do castelo, entre armadilhas e criaturas.
Dizem que a lança com que um rei abadrim matou o dragão era de uma liga mágica mais forte que o aço de Blur, e que ainda está escondida em algum canto de Tronum. As armas da Guarda da Lança estariam ali também, sob o pó e a relva.
Os bardos abadrim falam da coroa de Nurabissal, obra mágica de grandes poderes, roubada pouco antes da destruição da cidade. Quem a possuir, diz a lenda, poderá reerguer a glória de Abadom.$t$, false),
($t$ferco$t$, $t$Ruínas de Ferco$t$, $t$abadom$t$, NULL, $t$Ferco era o balneário de Abadom, lugar de descanso e diversão que os bardos ainda chamam de "a mais bela de todas" em canções melancólicas. Seus banhos e casas de diversão eram os melhores do reino, e ali se encontravam grandes comerciantes, a baixa nobreza e, às vezes, a alta.
A cidade ficava incrustada nas montanhas e foi uma das primeiras atacadas pelos dragões. Ninguém sabe o que foi feito de seus moradores.
Chamada de joia da costa ocidental, só perdia em riqueza para a capital. Suas lendas atraem aventureiros de muitas partes do mundo em busca de fortuna.$t$, $t$As canções dos bardos abadrim falam de uma casa inteira construída em ouro no meio de Ferco.$t$, false),
($t$petroferro$t$, $t$Minas de Petroferro$t$, $t$abadom$t$, NULL, $t$Petroferro foi talvez a maior mina de ferro do Mundo Conhecido, capaz de abastecer de minério o mundo inteiro, e era a fonte de lucro de todo o reino. Ficava perto de Tronum, junto ao mar.
Foi um dos primeiros lugares a cair quando os dragões atacaram. Desde então ninguém sabe dizer onde fica a entrada.$t$, NULL, false),
($t$cordilheira-de-sotopor$t$, $t$Cordilheira de Sotopor$t$, $t$abadom$t$, NULL, $t$A Cordilheira de Sotopor fecha o norte de Abadom e corre do litoral de Caleonir, a noroeste, até o Campo Branco. Guarda as maiores minas de minérios e pedras do Mundo Conhecido, mas o custo de explorá-las ainda é alto demais, e Acordo e Levânia as cobiçam de perto.
É um dos lugares mais letais de Tagmar. Nas suas cavernas vivem dragões, e por dentro das montanhas corre uma rede de túneis onde moram os dragonianos. Foi a seus pés que o exército da Seita sofreu a grande derrota de 1252 D.C.
Só ali, entre os Reinos, cresce o jaquepá, erva parda cujo chá os curandeiros usam contra todo tipo de doença e cuja semente entra nos elixires de regeneração.$t$, $t$Cantigas antigas falam de cidadelas proibidas e secretas na cordilheira, onde um povo meio humano, meio réptil vivia muito antes da chegada dos dragões e os adorava.
Dizem que das sombras das montanhas saem à noite espíritos agoniados, sedentos de sangue ou de coisa pior.
Aventureiros contam ouvir de noite um som como a marcha de centenas de búfalos selvagens seguindo em direção à cordilheira. Se é um exército de criaturas que se junta, ninguém sabe para quê; Calco e Plana pagam bem por notícia certa.$t$, false),
($t$pico-de-prussel$t$, $t$Pico de Prussel$t$, $t$abadom$t$, NULL, $t$O Pico de Prussel leva o nome de Prussel Dias Longos, rastreador elfo que foi o primeiro a subi-lo. É um dos maiores picos de Tagmar, talvez o maior, e fica nas montanhas vizinhas a Acordo.
Hoje é o covil dos dragões mais mortais que se conhecem. Dali partiram os ataques que devastaram Abadom.$t$, $t$Barqueiros de Plana contam que, há algumas décadas, uma tempestade nasceu no Lago Denégrio, na altura da ilha do misterioso Senhor do Lago, e atravessou as terras por dias até se assentar no topo do pico. Naquela que chamam de Noite das Chamas, os raios teriam queimado as asas dos dragões, e os arquivos de Calco falam em mais de trinta bestas mortas.$t$, false),
($t$templo-dos-delirios$t$, $t$Templo dos Delírios$t$, $t$abadom$t$, NULL, $t$O Templo dos Delírios é a sede de uma das ordens dedicadas a Plandis. Fica no extremo sul de Abadom, muito perto de onde as brumas de Dartel tocam a Levânia.$t$, NULL, false)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.npcs (slug, nome, raca, profissao, deus, idade, reino, cidade, descricao, rumores, compartilhado) VALUES
($t$eleriom_braco_forte$t$, $t$Eleriom Braço-Forte$t$, $t$Humano$t$, $t$Líder de Fleuter$t$, NULL, NULL, $t$abadom$t$, $t$fleuter$t$, $t$Eleriom Braço-Forte governa Fleuter, a única cidadela de Abadom ainda de pé. É um homem corpulento e de postura firme, que foi um grande guerreiro de seu povo e hoje é tratado com respeito por todos.
Os abadrim sabem que suas palavras pesam sobre a sobrevivência da cidadela. Ele mesmo resume o que ensina aos jovens: "Sobrevivência, filho, essa é a chave do sucesso em Abadom, pois aqui o que vale são as leis da natureza, onde o forte prevalece sobre o fraco."$t$, NULL, false),
($t$erdral_lanca_do_trovao$t$, $t$Erdral Lança do Trovão$t$, $t$Humano$t$, $t$Líder dos guerreiros de Fleuter$t$, NULL, $t$Na casa dos quarenta$t$, $t$abadom$t$, $t$fleuter$t$, $t$Erdral comanda os guerreiros de Fleuter e é tido por seu povo como o guerreiro mais poderoso ainda em armas. Defende os seus com ferocidade, e é capaz de grandes proezas.
Carrega a Lança do Trovão, de onde vem seu nome.$t$, $t$Dizem que a Lança do Trovão é uma das armas lendárias da Guarda da Lança de Tronum, forjadas com metais arcanos.$t$, false),
($t$evenezior_pernas_ligeiras$t$, $t$Evenezior Pernas Ligeiras$t$, $t$Humano$t$, $t$Rastreador, líder de Anguinadar$t$, NULL, NULL, $t$abadom$t$, $t$anguinadar$t$, $t$Evenezior lidera os abadrim nômades de Anguinadar em suas andanças pela margem do Lago Denégrio. É rastreador de renome, caçador talentoso e um dos batedores mais rápidos do reino.
Seus olhos percebem criaturas a centenas de passos, e graças a eles a vila escapa dos monstros que hoje tomam Abadom. Para seu povo, é um dos pilares que ainda o mantêm vivo.$t$, NULL, false),
($t$nurabissal$t$, $t$Nurabissal$t$, $t$Humano$t$, $t$Último rei de Abadom$t$, NULL, NULL, $t$abadom$t$, NULL, $t$Nurabissal foi o último rei de Abadom e viveu em Tronum, cercado por um harém de cinquenta mulheres e pelos tesouros tirados das minas do reino.
De seu reinado restam ruínas e uma coroa desaparecida.$t$, $t$Os bardos abadrim cantam que sua coroa era uma maravilha da magia daqueles tempos, roubada pouco antes de os dragões destruírem Tronum. Quem a possuir poderá reerguer a glória e o poder de Abadom.$t$, false)
ON CONFLICT (slug) DO NOTHING;

-- ── calco ──
INSERT INTO public.cidades (slug, nome, reino, capital, populacao, governante, religiao, economia, descricao, rumores, compartilhado) VALUES
($t$saravossa$t$, $t$Saravossa$t$, $t$calco$t$, true, NULL, $t$Rei Hemilanor, assistido pela Casa Ministerial$t$, $t$Palier e Selimom, com templos para todos os deuses; ali ficam o maior templo de Cruine de Tagmar e o Templo de Cambu$t$, $t$Vive do saber: estudiosos de todo o mundo pagam por mapas, fórmulas mágicas e consultas à Biblioteca Central. A Praça de Cambu vende mercadorias de todo o Mundo Conhecido, e o porto leva cada vez mais passageiros que carga.$t$, $t$Capital de Calco, à beira do Mar do Norte, cercada de mato baixo e com um bosque ao sul. Nasceu das ruínas da fortaleza de Saravos, tomada do tirano orco Korumba em 344 D.C., e foi a capital dos moldas desde que Sivom ocupou a Sagasta, o Trono da Aliança. Na guerra da Seita foi a última cidade a resistir aos 13 Senhores Infernais; na Unificação, todos os reinos mandavam para cá seus representantes. Hoje abriga o Palácio Real, a Casa Ministerial, os principais colégios de magia e quase todos os templos e centros de estudo do reino.
A cidade tem cinco partes. O porto é pequeno e dos mais movimentados do mundo, e à noite O Farol o cobre de luz mágica para guiar os barcos perdidos. A noroeste fica a Praça de Cambu, de ruas limpas e largas, onde se compra de tudo menos escravos, abolidos pelo Grande Sábio; ali estão as tabernas, os prostíbulos e o Templo de Cambu. Colada à praça, a sudoeste, a Área dos Artesãos reúne artífices de nome, como o escultor Heitor de CostaSalva, o construtor de barcos Celebriem de Novo Porto e o ferreiro anão Mélom Punho de Martelo.
No centro, sobre uma elevação, ergue-se o Palácio Real, todo de calcário, com a entrada desenhada em mármore e pedras semipreciosas. Foi construído para guardar o corpo do Grande Sábio Malim, que repousa atrás do trono. No salão real está montado o esqueleto de um dragão achado morto no sul depois da guerra com o Senhor do Lago Denégrio; os arquivos do reino o ligam à Noite das Chamas. Em frente fica a Casa da Ordem Ministerial, de madeira de alerubra, coberta de afrescos de artesãos de várias cidades.
A leste vivem os moradores: na parte nobre, as mansões dos lordes, que se hospedam ali nas festas dos deuses; na Área dos Templos, os colégios de magia, as fontes naturais que abastecem a cidade e a Biblioteca Central, a maior do Mundo Conhecido, cuidada pelos sacerdotes do Templo de Palier, com quem divide o prédio; no subúrbio, a gente comum, os pequenos comerciantes e as tabernas. Junto ao grande templo de Cruine estende-se o maior cemitério de Tagmar, onde jazem grandes reis e aonde os peregrinos vão rezar no Dia de Cruine. A Sociedade de Malim, magos da linhagem de Mermex de Quizes, tem sede na cidade, cujos limites legais seguem pela estrada do sul até o Moinho de Vento.$t$, $t$No subúrbio, gente de várias raças aparece morta nos becos que dão para fora da cidade. Quem viu os corpos diz que estavam sem olhos, com as órbitas vazias e nenhum sangue ao redor, e que são levados ao templo de Cruine por medo de que se levantem.
Fala-se de um culto demonista nos arredores que tenta trazer os mortos de volta para entender o que se passou no tempo do Grande Sábio. Esses mortos viriam de noite à orla da cidade comer carne humana, ou coisa pior.
Dizem que a Biblioteca Central guarda, trancados a sete chaves, livros de magia do Segundo Ciclo com encantos como o que teria criado, ou devastado, o Campo Branco, ou o que expulsou os demônios. Os sacerdotes e acólitos que lá trabalham não confirmam.
Conta-se que há representantes do pouco conhecido Império entre os alunos das escolas da cidade.
Poucos sabem qual foi a missão que o rei Hemilanor cumpriu na Cerimônia de Gultar, quando passou um ano fora do reino.$t$, false),
($t$malocai$t$, $t$Malocai$t$, $t$calco$t$, false, NULL, NULL, NULL, $t$Fabrica manufaturas o ano inteiro e as embarca para as cidades da costa leste do mundo.$t$, $t$Cidade portuária no leste de Calco, quase toda voltada a fazer e despachar mercadorias. Suas oficinas trabalham em todas as estações, e o porto escoa o que sai delas rumo às cidades da costa leste.
É um dos berços das famílias de nobres comerciantes mais ricas do reino, e essas famílias pesam na política: Malocai, como as demais cidades principais, elege um conselheiro para a Casa Ministerial a cada vinte anos.$t$, $t$As más línguas dizem que Malocai tenta impor novas regras portuárias que abririam caminho para muito negócio ilícito. Nobres comerciantes buscariam vantagens elegendo Ivam Areus, Conde de Darfam, filho de um dos comerciantes mais ricos da cidade, como conselheiro de Malocai; ele seria ainda forte candidato a Tesoureiro do Rei, o cargo que dita as regras do comércio. Há quem veja nisso o começo de um complô.$t$, false),
($t$carom$t$, $t$Carom$t$, $t$calco$t$, false, NULL, NULL, NULL, $t$Abastece o reino de pescado e das iguarias da ilha do delta, como a erva de rabeira, vendidas caro em Saravossa.$t$, $t$Cidade de pescadores perto do delta do Rio Traço, com a maior concentração de elfos de Calco. É lembrada como exemplo de cidade erguida sem destruir a mata e as águas em volta.
Da ilha do delta vêm iguarias que não existem em outro lugar. A mais procurada é a erva de rabeira, de que se faz um unguento bom para muitos tipos de ferimento. Peixe e erva recebem um trato mágico para não estragar na estrada e chegam aos mercados de Saravossa a preços altos.$t$, NULL, false),
($t$bassani$t$, $t$Bassani$t$, $t$calco$t$, false, NULL, NULL, NULL, $t$Recebe minério de Acordo, embarca o ouro e a prata de Torojai e escoa a produção do reino pela costa oeste. Constrói e conserta navios e começa a trabalhar o metal.$t$, $t$Porto da costa oeste de Calco e o principal de onde partem, todos os dias, os barcos do comércio com Plana, hoje muito intenso. Pelas suas docas passam o minério que chega de Acordo e o que desce de Torojai.
Os estaleiros da cidade fazem e reparam embarcações. Boa parte dos anões do reino passa por aqui, e Bassani já fabrica peças de metal, ainda em pouca quantidade.$t$, $t$Dizem que a sede da guilda de ladrões de Calco, ou talvez dos piratas, fica em Bassani.
Nas docas corre que o movimento de navios para Plana está agitando os piratas nas águas do Mar do Norte, antes calmas. Fala-se no lendário Veros Negro, do Capitão Zaras Arcos de Fogo, armado de arbalestas encantadas que disparam flechas de fogo elemental que nem a água do mar apaga.$t$, false),
($t$torojai$t$, $t$Torojai$t$, $t$calco$t$, false, NULL, NULL, NULL, $t$Vive do ouro e da prata tirados da Serra de Saupami e compra das outras cidades quase tudo o que come, pois a terra em volta é estéril. Seus chefes mineradores estão entre os homens mais abastados do reino.$t$, $t$Cidade mineira que cresceu muito além de sua irmã, Saupami. A virada veio com a redescoberta de uma estrada esquecida havia muito tempo: anões acharam grandes veios na Serra de Saupami, trouxeram mineradores para uma região antes sem valor, e uma estrada nova foi aberta cortando a serra.
Torojai tem uma das maiores colônias de anões dentro de uma cidade humana, e é ali, mais até que em Saravossa, que se compram as finas obras e armas feitas pelos anões. Seu chão não dá sustento, e ela importa de tudo; mesmo assim é uma das cidades mais ricas de Calco.$t$, NULL, false),
($t$saupami$t$, $t$Saupami$t$, $t$calco$t$, false, NULL, NULL, NULL, $t$Fornece as matérias-primas vegetais do reino, para tinta, tecido e remédio, e os cereais mais valiosos de Calco, o trigo e a cevada.$t$, $t$Saupami fica a meio caminho de tudo em Calco. De suas terras saem as plantas que o reino usa para tingir, tecer e fazer remédios.
O solo rico, entre duas florestas, dá o trigo e a cevada de maior valor do reino; a cevada vai em boa parte para as mesas dos nobres de Saravossa. Foi a cidade irmã que ficou para trás quando Torojai enriqueceu com as minas da serra que leva o nome de Saupami.$t$, NULL, false),
($t$toria$t$, $t$Tória$t$, $t$calco$t$, false, NULL, NULL, $t$Sevides, cujo templo guarda o Arado de Ouro$t$, $t$Uma das maiores produtoras de grãos do Mundo Conhecido: arroz, feijão, milho e o grão-de-bico de Tória, vendidos sobretudo para Plana.$t$, $t$Terra de lavoura, que vive de plantar e de vender grãos a Plana. O grão-de-bico de Tória é famoso, e o segredo do seu plantio pertence a uma só família, uma das mais antigas da cidade.
No templo de Sevides está o Arado de Ouro, um dos grandes objetos sagrados do deus. Por causa dele, a região de Tória é tida como a terra mais fértil de Tagmar, acima até das de Eredra.$t$, $t$Dizem que o Arado de Ouro tem enormes poderes divinos, e há lendas de que sobre ele pesa uma grande maldição.$t$, false),
($t$abrasil$t$, $t$Abrasil$t$, $t$calco$t$, false, NULL, NULL, $t$Lena$t$, $t$Uma das maiores produtoras de vinho do mundo, também afamada pelas bebidas fermentadas. Seus mercados vendem curiosidades de todos os cantos de Tagmar.$t$, $t$No sul de Calco, a única cidade conhecida fundada por pequeninos, povo que costuma viver em vilas pequenas. Sua fundação remonta ao início do império molda, e a ela chegam pequeninos de todo o reino e do Mundo Conhecido; a população cresce ano a ano com os que imigram.
Suas festas passam pelas melhores do reino, e seu vinho é apreciado em toda parte. Os anões de Ludgrim têm um ditado: “A cerveja de Abrasil, a perrita de Dantsem e o fumo de Ludgrim: os pequeninos, sem saberem, já conquistaram Tagmar!”
No Mês da Água, o segundo do ano, Abrasil celebra a Festa da Carne em honra a Lena, com dança e canto. As famílias reúnem todas as gerações e assam o boi mais viril e bonito que conseguem comprar; o símbolo da festa são dois bois de ouro frente a frente, em pose de combate, com uma flor dourada entre eles.$t$, $t$Entre as quinquilharias trazidas de toda parte para os mercados de Abrasil, dizem que há até objetos mágicos.$t$, false)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.locais (slug, nome, reino, populacao, descricao, rumores, compartilhado) VALUES
($t$floresta-de-aberdim$t$, $t$Floresta de Aberdim$t$, $t$calco$t$, NULL, $t$A mais densa das matas que restaram em Calco, depois que a grande floresta do reino foi quase toda derrubada, e o único lugar do reino que dá madeira de lei. É mata tropical úmida, terra de grandes símios, tigres, panteras e onças.
Uma colônia de meio-elfos e humanos tira dali a alerubra com cuidado para não ferir a floresta. A árvore tem tronco grosso e rombudo e dá uma madeira escura, meio carmim como o mogno, que resiste ao tempo melhor que ele; é dela a Casa Ministerial de Saravossa. Ao norte da floresta erguem-se os montes de onde os anões tiram boa parte do minério de Calco.$t$, NULL, false),
($t$serra-de-saupami$t$, $t$Serra de Saupami$t$, $t$calco$t$, NULL, $t$Serra perto de Saupami onde anões descobriram grandes veios de ouro e prata. A região era tida como de pouco valor até que uma estrada antiga, abandonada havia muito, voltou a ser usada.
Com a descoberta vieram mineradores de fora e uma estrada nova, aberta cortando a serra. O minério que sai dali fez a riqueza de Torojai e desce até Bassani para ser embarcado.$t$, NULL, false),
($t$moinho-de-vento$t$, $t$Moinho de Vento$t$, $t$calco$t$, NULL, $t$Moinho na estrada do sul, perto da Pequena Floresta de Saravossa, onde terminam os limites legais da capital. Ali mora a maga Arísia Olhosclaros, guardiã do lugar.
Dentro do moinho fica um astrolábio, que Arísia guarda com a filha adotiva, a maga Sarana Olhosclaros.$t$, NULL, false),
($t$rio-frefo$t$, $t$Rio Frefo$t$, $t$calco$t$, NULL, $t$Rio da fronteira oeste de Calco, que o separa de Plana. Foi ao grande Vale do Frefo que os moldas chegaram por volta de 200 D.C., numa terra então dominada por monstros.
Não há cidade grande às suas margens, só muitas vilas ribeirinhas que vivem da pesca e de vender a travessia para a margem ocidental. Nas vilas da margem leste há pequenas capelas de Selimom.$t$, $t$Nas vilas ribeirinhas, há quem jure ter visto uma criatura monstruosa, enorme, vagando pelas águas do Frefo em noites de lua cheia.$t$, false)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.npcs (slug, nome, raca, profissao, deus, idade, reino, cidade, descricao, rumores, compartilhado) VALUES
($t$sarana_olhosclaros$t$, $t$Sarana Olhosclaros$t$, $t$Humano$t$, $t$Maga$t$, NULL, NULL, $t$calco$t$, $t$saravossa$t$, $t$Maga humana, filha adotiva de Arísia Olhosclaros. Vive com ela no Moinho de Vento, nos limites de Saravossa, e as duas cuidam do astrolábio guardado ali dentro.$t$, NULL, false),
($t$eidolom_gibral_de_ender$t$, $t$Eidolom Gibral de Ender$t$, NULL, $t$Mago elementalista$t$, NULL, NULL, $t$calco$t$, $t$saravossa$t$, $t$Mago elemental da Sociedade de Malim, o grupo de magos da linhagem de Mermex de Quizes que tem sede em Saravossa. É amigo de Mermex, de Arísia Olhosclaros e de Divanor Isonar, e, como eles, seu nome corre todo o Mundo Conhecido.$t$, NULL, false),
($t$sedro_aqueno$t$, $t$Sedro Aqueno$t$, NULL, $t$Mercador e armador$t$, NULL, NULL, $t$calco$t$, $t$saravossa$t$, $t$Comerciante famoso do porto de Saravossa. Passou a usar seus barcos para levar gente em vez de carga, um negócio que ninguém em Tagmar explorava, e hoje domina as viagens de passageiros que saem da capital.
É contra os planos de ampliar o porto com novas docas e armazéns.$t$, NULL, false),
($t$veristi$t$, $t$Veristi$t$, NULL, $t$Sacerdote de Cambu$t$, $t$Cambu$t$, NULL, $t$calco$t$, $t$saravossa$t$, $t$Sacerdote do Templo de Cambu, o maior marco da praça comercial de Saravossa. Recebe ali as oferendas dos fiéis e recolhe os impostos devidos ao reino.$t$, NULL, false),
($t$heitor_de_costasalva$t$, $t$Heitor de CostaSalva$t$, NULL, $t$Escultor$t$, NULL, NULL, $t$calco$t$, $t$saravossa$t$, $t$Escultor da Área dos Artesãos de Saravossa, contado entre os mais conceituados que ainda vivem. Seu nome é conhecido em todo o mundo.$t$, NULL, false),
($t$celebriem_de_novo_porto$t$, $t$Celebriem de Novo Porto$t$, $t$Meio-Elfo$t$, $t$Construtor de barcos$t$, NULL, NULL, $t$calco$t$, $t$saravossa$t$, $t$Meio-elfo da Área dos Artesãos de Saravossa que faz os melhores barcos do Mundo Conhecido, segundo ele mesmo.$t$, NULL, false),
($t$melom_punho_de_martelo$t$, $t$Mélom Punho de Martelo$t$, $t$Anão$t$, $t$Ferreiro armeiro$t$, NULL, NULL, $t$calco$t$, $t$saravossa$t$, $t$Ferreiro anão da Área dos Artesãos de Saravossa. Forja as armas dos nobres mais poderosos de Calco.$t$, NULL, false),
($t$ivam_areus$t$, $t$Ivam Areus$t$, NULL, $t$Conde de Darfam$t$, NULL, NULL, $t$calco$t$, $t$malocai$t$, $t$Conde de Darfam, filho de um dos comerciantes mais ricos de Malocai. É o nome que os nobres comerciantes da cidade querem eleger conselheiro de Malocai na Casa Ministerial, e é forte candidato a Tesoureiro do Rei, cargo que dita as regras do comércio.$t$, $t$Dizem que sua eleição faz parte de uma manobra dos comerciantes de Malocai para afrouxar as regras do porto e facilitar negócios ilícitos.$t$, false),
($t$zaras_arcos_de_fogo$t$, $t$Zaras Arcos de Fogo$t$, NULL, $t$Capitão pirata$t$, NULL, NULL, $t$calco$t$, NULL, $t$Capitão do Veros Negro, navio pirata lendário. O comércio crescente entre Calco e Plana estaria atraindo-o, com outros piratas, para as águas do Mar do Norte.$t$, $t$Contam nas docas de Bassani que o Veros Negro leva grandes arbalestas encantadas, capazes de disparar flechas velozes de fogo elemental que nem a água do mar apaga.$t$, false)
ON CONFLICT (slug) DO NOTHING;
UPDATE public.reinos SET capital = $t$saravossa$t$ WHERE slug = $t$calco$t$ AND capital IS NULL;

COMMIT;

