-- ------------------------------------------------------------------
-- CORREÇÃO (08/11/2026): duplicatas. O usuário: "Você criou algumas cidades
-- duplicadas, como Aberdim e Crássia." Essas cidades (e Deiamom, Tronum,
-- Eleriom, Erdral, Evenezior) já existiam na história 13, com população e
-- governante; a conferência acima só olhou o catálogo global. As linhas da
-- história ficam, as globais saem, e quem apontava para elas é religado.
-- ------------------------------------------------------------------
BEGIN;
CREATE TEMP TABLE mapa(novo text, velho text) ON COMMIT DROP;
INSERT INTO mapa VALUES
('aberdim','nova-cidade-h13-2f69d444'),('abrasil','nova-cidade-h13-51a85e68'),('bassani','nova-cidade-h13-0826c8a8'),
('carom','nova-cidade-h13-ed90ff84'),('crassia','nova-cidade-h13-34b05f15'),('fleuter','nova-cidade-h13-6f1e3104'),
('fontenova','nova-cidade-h13-abf93e1d'),('lutrucia','nova-cidade-h13-8a5379e6'),('malocai','nova-cidade-h13-ff43cc05'),
('saravossa','nova-cidade-h13-35a4b3e2'),('saupami','nova-cidade-h13-360a0ed2'),('seviala','nova-cidade-h13-629ef032'),
('sula','nova-cidade-h13-229567ad'),('toria','nova-cidade-h13-5a507ad0'),('torojai','nova-cidade-h13-266ab50f'),
('treva','nova-cidade-h13-7555c45f');
UPDATE npcs n SET cidade = m.velho FROM mapa m WHERE n.cidade = m.novo;
UPDATE reinos r SET capital = m.velho FROM mapa m WHERE r.capital = m.novo;
DELETE FROM npcs WHERE historia_id IS NULL AND slug IN ('eleriom_braco_forte','erdral_lanca_do_trovao','evenezior_pernas_ligeiras');
DELETE FROM locais WHERE historia_id IS NULL AND slug IN ('tronum','deiamom');
DELETE FROM cidades c USING mapa m WHERE c.historia_id IS NULL AND c.slug = m.novo;
COMMIT;
